　暖かい空気は軽いので上へ行きたがる。煙突の中の空気が外より
　暖かければ、その浮力で上向きの流れが生まれ、下からは新しい
　空気が入ってくる。これが温度差換気。風が吹けば、風上側の
　壁は押されて正圧、風下側は引かれて負圧となり、圧力差で
