　共鳴透過｜低音域で低下★｜二重壁の空気バネ

・単層壁の透過損失は面密度と周波数の対数に比例する（質量則）。
　面密度または周波数が2倍で約6dB増える★
・低音ほど透過損失が小さく、遮音しにくい★
・コインシデンス効果は、板の曲げ波と入射音の波長が一致して
　透過損失が落ち込む現象。薄い板ほど高い周波数で生じる★
・二重壁は同じ質量の単層壁より高性能だが、中空層の空気バネと
　両壁の質量で決まる共鳴透過周波数で性能が落ちる★
