・急速ろ過はろ過速度120〜150m/日程度、緩速ろ過は4〜5m/日程度で、
　緩速ろ過は生物膜による浄化作用を利用する★
・高度浄水処理はオゾン処理と活性炭吸着を組み合わせ、
　かび臭やトリハロメタン前駆物質を除去する★
・塩素消毒の副生成物としてトリハロメタンが生成する。
