【図解】水質に起因する障害
　水質｜障害｜対策
　高硬度｜スケール（炭酸カルシウム）付着★｜軟水化・薬注
　遊離炭酸が多い｜銅管などの腐食★｜脱気・pH調整
　溶存酸素が多い｜鋼管の腐食★｜脱気・密閉系化
　塩化物イオンが多い｜ステンレスの孔食★｜材質選定

・硬度はカルシウムイオンとマグネシウムイオンの量を
