　防虫網を設けて排水管と直結しない★
・貯水槽の清掃は1年以内ごとに1回、水質検査は法令に基づき
　定期に実施する★
・滞留水は残留塩素が消費されるため、水槽の容量が大きすぎると
　水質が悪化する。1日使用水量の40〜60%程度が目安★
・クロスコネクション（飲料水系統と他系統の直結）は
　絶対に禁止。誤接続は重大な健康被害につながる★

