　層流｜λ＝64/Re★｜粗さ無関係
　なめらか管乱流｜Reのみで決まる★｜ブラジウスの式
　遷移域｜Reと相対粗さ★｜ムーディ線図
　完全乱流域｜相対粗さのみ★｜Reに依存しない

・ムーディ線図は、横軸にRe、縦軸にλ、パラメータに
　相対粗さ（ε/d）をとった図で、λを読み取るのに用いる★
・相対粗さは絶対粗さεを管内径dで割った値。同じ材質でも
　細い管ほど相対粗さが大きく、λが大きくなる★
・鋼管は経年で内面にスケールや腐食生成物が付き、粗さが増して
　λが大きくなる。設計では経年係数を見込む★
