━━━━━━━━━━━━━━━━━━━━━━
・高層建物では、静水圧が過大にならないよう、給水を
　中間水槽や減圧弁で複数のゾーンに分ける（ゾーニング）★
・冷温水系統では、開放式では膨張タンクの位置が系統内圧力の
　基準となり、密閉式では膨張管の接続点が基準となる★
・ポンプの吸込み側に膨張タンクを接続すると、系統全体が
　正圧に保たれ、空気の吸込みを防げる★
・バランシングバルブは流量測定機能を備え、各系統の流量を
