━━━━━━━━━━━━━━━━━━━━━━
・過負荷保護にはサーマルリレー（熱動継電器）を用い、
　定格電流に合わせて整定する★
・欠相・逆相・過負荷を検出する2E・3Eリレーは、
　電動機の焼損防止に有効★
・電動機の効率は定格付近で最も高く、過大な容量を選ぶと
